<?php
declare(strict_types=1);
$selectedPerson=max(0,(int)($_GET['person_id']??0));$rulePeriod=(string)($_GET['rule_period']??$currentPeriod);
try{memberFeePlanMonth($rulePeriod);}catch(InvalidArgumentException){$rulePeriod=$currentPeriod;}
$allMembers=memberFeePlanEligibleMembers($pdo,$selectedPlan,$rulePeriod.'-01',(new DateTimeImmutable($rulePeriod.'-01'))->format('Y-m-t'));
$payerOptions=[];$agreement=null;$decision=null;
if($selectedPerson>0){
 $q=$pdo->prepare("SELECT DISTINCT a.id,a.jmeno,a.prijmeni,a.email FROM verejni_uzivatele a JOIN account_person_roles r ON r.account_id=a.id WHERE r.sportovec_id=? AND r.status='approved' AND r.relation_role IN ('self','guardian') AND a.aktivni=1 AND a.email_overeno=1 AND r.valid_from<=CURRENT_TIMESTAMP AND (r.valid_to IS NULL OR r.valid_to>CURRENT_TIMESTAMP)");$q->execute([$selectedPerson]);$payerOptions=$q->fetchAll(PDO::FETCH_ASSOC);
 $q=$pdo->prepare('SELECT * FROM member_fee_agreements WHERE plan_id=? AND sportovec_id=? ORDER BY id DESC LIMIT 1');$q->execute([$selectedPlan,$selectedPerson]);$agreement=$q->fetch(PDO::FETCH_ASSOC);
 $q=$pdo->prepare('SELECT * FROM member_fee_period_decisions WHERE plan_id=? AND sportovec_id=? AND period_key=? ORDER BY id DESC LIMIT 1');$q->execute([$selectedPlan,$selectedPerson,$rulePeriod]);$decision=$q->fetch(PDO::FETCH_ASSOC);
}
?>
<section class="card card-body mb-4"><h2 class="h5">Dohoda plátce a schválení částky</h2><p>U každé osoby určete sjednaného plátce a přesnou částku za měsíc. Nulová částka znamená doložené prominutí, nevytváří příjem. Vstup uprostřed měsíce, přerušení a souběh plánů se posuzují výslovně. Pokud již měsíční běh proběhl, doplnění nového člena řešte v <a href="member_charges_admin.php">Jednotlivých předpisech</a> s odkazem na dohodu; opakování běhu nevytváří druhé předpisy.</p>
<form method="get" class="row g-2"><input type="hidden" name="plan_id" value="<?=$selectedPlan?>"><div class="col-md-3"><label>Měsíc<input class="form-control" type="month" name="rule_period" value="<?=mfph($rulePeriod)?>" required></label></div><div class="col-md-5"><label>Osoba<select class="form-select" name="person_id"><option value="">Vyberte</option><?php foreach($allMembers as$m):?><option value="<?=(int)$m['id']?>" <?=$selectedPerson===(int)$m['id']?'selected':''?>><?=mfph($m['prijmeni'].' '.$m['jmeno'])?></option><?php endforeach;?></select></label></div><div class="col-md-3"><button class="btn btn-outline-primary mt-4">Otevřít dohodu</button></div></form>
<?php if($selectedPerson>0):?><div class="row g-3 mt-2"><div class="col-md-6"><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="agreement"><input type="hidden" name="plan_id" value="<?=$selectedPlan?>"><input type="hidden" name="sportovec_id" value="<?=$selectedPerson?>"><input type="hidden" name="expected_id" value="<?=(int)($agreement['id']??0)?>"><label>Výslovně sjednaný plátce<select class="form-select" name="payer_account_id" required><option value="">Vyberte podle dohody</option><?php foreach($payerOptions as$payer):?><option value="<?=(int)$payer['id']?>"><?=mfph($payer['prijmeni'].' '.$payer['jmeno'].' · '.$payer['email'])?></option><?php endforeach;?></select></label><div class="row"><label class="col">Od<input class="form-control" type="date" name="valid_from" value="<?=mfph($rulePeriod.'-01')?>" required></label><label class="col">Do<input class="form-control" type="date" name="valid_to" value="<?=mfph((new DateTimeImmutable($rulePeriod.'-01'))->format('Y-m-t'))?>" required></label></div><label>Podklad dohody<input class="form-control" name="reason" required minlength="5"></label><label class="d-block"><input type="checkbox" name="confirmed" value="1" required> Potvrzuji sjednaného plátce a platnost</label><button class="btn btn-primary">Uložit dohodu plátce</button></form></div>
<div class="col-md-6"><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="decision"><input type="hidden" name="plan_id" value="<?=$selectedPlan?>"><input type="hidden" name="sportovec_id" value="<?=$selectedPerson?>"><input type="hidden" name="period" value="<?=mfph($rulePeriod)?>"><input type="hidden" name="expected_id" value="<?=(int)($decision['id']??0)?>"><label>Schválená částka za <?=mfph($rulePeriod)?> v Kč<input class="form-control" name="amount_czk" inputmode="decimal" value="<?=mfph(number_format((int)($decision['amount_minor']??$plan['amount_minor'])/100,2,'.',''))?>" required></label><label>Důvod a schválené pravidlo<input class="form-control" name="reason" required minlength="5" placeholder="Plný měsíc / přesně schválená úleva"></label><label class="d-block"><input type="checkbox" name="allow_overlap" value="1"> Schvaluji souběžný předpis z dalších plánů</label><label class="d-block"><input type="checkbox" name="confirmed" value="1" required> Potvrzuji přesnou částku a důvod</label><button class="btn btn-primary">Schválit částku období</button></form></div></div><?php endif;?></section>
